############# # Load Macros #############
loadMacros( "PGstandard.pl", "PGML.pl", "AnswerFormatHelp.pl", "PGchoicemacros.pl", "contextForm.pl", "ORCCA.pl", "PGcourse.pl", ); COMMENT('Authored in PreTeXt');
####### # Setup #######
Context("Form"); $var = list_random('a'..'n', 'p'..'z', 'A'..'D', 'F'..'N', 'P'..'T', 'V'..'Z'); Context()->variables->are($var => 'Real'); do { ($a, $b, $c, $d, $e, $f) = (2..9)[NchooseK(8,6)]; $abde = $a*$b - $d*$e; $acdf = $a*$c - $d*$f; } until ($abde != 0 && $acdf != 0); $given = Formula("$a($b $var + $c) - $d($e $var + $f)"); $ans = Formula("$abde $var + $acdf");
############################# # Exercise Group Introduction #############################
BEGIN_PGML Simplify the given expression. Ideally, you are thinking about how the properties of algebra are helping you simplify.
END_PGML
###### # Body ######
BEGIN_PGML [`[$given]`]
[_]{$ans}{16}
END_PGML
